head.script:
scwin.setColumnID = function(obj) {
    //debugger;
    var column = {};
    var columnArr = [];
    var gridHeader = "",
        gridBody = "";
    //json의 첫번째 데이터에서 컬럼의 id와 개수 정보 확
    for (var k in obj[0]) {
        //dataList를 동적으로 만들기 위한 컬럼 정
        column = {};
        column["id"] = k;
        column["dataType"] = "text";
        columnArr.push(column);
        //gridView의 컬럼 정보 정의
        gridHeader += '<w2:column blockSelect="false" id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
        if (k == 'col1') {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
        } else {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
        }
    }
    //gridView 정보 정의
    //xml 형식을 정의 하면 <w2:gridView 에 xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" 포함 합니다.
    var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" scrollByColumn="false" id="gridView1" style="width: 500px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" ev:ongroupby="scwin.ongroupby" autoFit="allColumn" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" rowNumWidth="" >' +
        '<w2:header id="header1" style="">' +
        '<w2:row id="row1" style="">' +
        gridHeader +
        '</w2:row>' +
        '</w2:header>' +
        '<w2:gBody id="gBody1" style="">' +
        '<w2:row id="row2" style="">' +
        gridBody +
        '</w2:row>' +
        '</w2:gBody>' +
        '</w2:gridView>';
    gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
    //dataList1.setJSON(obj);
}
scwin.ongrp = function(options) {
    options.groupbyHeader = [];
    options.groupbyFooter = [];
    gridView1.groupby(options);
};
scwin.ongroupby = function(options) {
    options.groupbyHeader = [];
    options.groupbyFooter = [];
    this.groupby(options);
    return false;
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].checked == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].checked == true;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[3].checked == false;
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[4].checked == false;
}
scwin.checkVal5 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[5].checked == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행후'동적그리드'버튼을 클릭한다.
    //1. After running the sample, click the 'Dynamic Grid' button.
    //Verify step 1. The gridview screen is changed.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_hcol0').text() == 'col0'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_hcol1').text() == 'col1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_hcol2').text() == 'col2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_hcol3').text() == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'col0'항목의 값을 '0'으로 필터링한다.
    //2. Filter the value of the 'col0' item to '0'.
    //Verify step 2. Filtered to a value of '0'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_hcol0_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. '동적그리드'버튼을 2번 클릭하고 '0'값의 필터링이 유지되는지를 확인한다.
    //3. Double-click the 'Dynamic Grid' button and verify that filtering of the '0' value is maintained.
    //Verify step 3. Filtering of '0' values is maintained and shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_hcol0_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_hcol0_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
